from ute_core.exception import CoreException


class AsyncException(CoreException):
    """Exception is raised in case of any error in ute_async library."""


class KeywordSearchError(AsyncException):
    """Exception is raised if ute_async is not able to find specified keyword."""


class EmptyResult(AsyncException):
    """Exception is raised if execution result is not available."""
